/**
 * Shared base for every per-variant aspect field input. Mirrors
 * `AbstractAspectFieldInput<T>` on ultron — every concrete variant
 * extends it with variant-specific extras (e.g. `mediaTypes` on
 * attachment fields, `format` on numeric fields).
 *
 * `defaultValue` is `unknown` because each variant constrains it
 * differently (e.g. `boolean` vs `string` vs `string[]`); the SDK
 * doesn't mediate the value beyond passing it to ultron.
 */
export interface AspectFieldBaseInput {
    readonly id?: string;
    readonly clientHandle?: string;
    readonly name: string;
    readonly columnName?: string;
    readonly required?: boolean;
    readonly requiredOnClose?: boolean;
    readonly showOnCreate?: boolean;
    readonly description?: string;
    readonly tags?: readonly string[];
    readonly lockOnCreate?: boolean;
    readonly defaultValue?: unknown;
}
